/* Viðbótarspurningar nýta sniðmát, biðraðajöfnur og sjónræna merkingu BPMN-tákna. */
globalThis.EXTRA_QUESTIONS=(()=>{
  const questions=[];
  function add(lecture,topic,kind,stem,options,explanation,file,pages,diagram){questions.push({id:'extra-'+String(questions.length+1).padStart(3,'0'),group:'bpm',lecture,topic,kind,stem,options,answer:0,explanation,source:{file,pages},...(diagram?{diagram}:{})});}
  const raci='RACI_sniðmát_ppt (1).pptx',sipoc='SIPOC_sniðmát_ppt (1).pptx',queue='MMc raðir - kafli 7.2 Ítarefni.png',f3='F3 - Ferlalíkön (1).pdf',f4='F4 - Þróuð Ferlalíkön (1).pdf';
  add('F2','RACI','application','Við uppfærslu verklags skrifar Anna nýju lýsinguna. Bjarni ber endanlega ábyrgð á að hún sé rétt og samþykkir hana. Hvernig á að skrá hlutverk þeirra í RACI?',['Anna er Responsible og Bjarni Accountable.','Anna er Accountable og Bjarni Responsible.','Anna er Informed og Bjarni Consulted.','Bæði eru Informed því þau þekkja verklagið.'],'Responsible vinnur verkið. Accountable ber endanlega ábyrgð á niðurstöðunni og samþykki hennar.',raci,[1]);
  add('F2','RACI','application','Lögfræðingur gefur ráð meðan nýtt ferli er hannað og teymið ræðir við hann um áhrif tillagna. Hvaða RACI-hlutverk lýsir þessari þátttöku?',['Consulted.','Informed.','Responsible fyrir öllu ferlinu.','Accountable fyrir öllum ákvörðunum.'],'Consulted felur í sér ráðgjöf og tvíhliða samskipti. Informed lýsir því að fá upplýsingar, án sams konar ráðgjafarhlutverks.',raci,[1]);
  add('F2','RACI','application','Þjónustuver þarf að fá tilkynningu um samþykkta breytingu en tekur ekki þátt í að semja eða samþykkja hana. Hvert er hlutverk þess í RACI fyrir breytingaverkið?',['Informed.','Consulted.','Accountable.','Responsible.'],'Þjónustuverið þarf upplýsingar um niðurstöðuna. Það framkvæmir ekki breytingaverkið, samþykkir það ekki og veitir ekki ráð við gerð þess í þessu dæmi.',raci,[1]);
  add('F2','SIPOC','application','Verkstæði fær bilanatilkynningu frá viðskiptavini, gerir við tækið og afhendir það viðgert. Hvar á bilanatilkynningin heima í SIPOC?',['Innlag (Input).','Birgi (Supplier).','Frálag (Output).','Viðskiptavinur (Customer).'],'Tilkynningin er upplýsingar sem fara inn í ferlið. Aðilinn sem leggur þær til er birgi; viðgert tæki er frálag.',sipoc,[2]);
  add('F2','SIPOC','application','Launadeild fær samþykktar tímaskýrslur frá verkstjórum og skilar launaútreikningi til greiðsludeildar. Hver er viðskiptavinur þessa afmarkaða ferlis í SIPOC?',['Greiðsludeildin sem tekur við launaútreikningnum.','Verkstjórarnir sem afhenda tímaskýrslurnar.','Samþykktu tímaskýrslurnar sjálfar.','Launaforritið sem framkvæmir reikningana.'],'Customer er viðtakandi frálags innan valinna ferlamarka og getur verið innri aðili. Verkstjórar eru birgjar innlags í þessu dæmi.',sipoc,[2]);
  add('F2','SIPOC','application','Hópur er að byrja ferlaskráningu og vill skýra helsta innlag, frálag og viðtakendur áður en hvert verk er útfært. Hvað hentar best?',['Gera SIPOC-yfirlit af afmörkuðu ferlinu.','Skrá aðeins skipurit fyrirtækisins.','Velja strax hugbúnað fyrir hvert skref.','Gera RACI-töflu í stað þess að skilgreina innlag og frálag.'],'SIPOC sýnir Supplier, Input, Process, Output og Customer. Það styður afmörkun og heildarmynd áður en farið er dýpra í verkþætti.',sipoc,[1,2]);
  add('F7','Biðraðir','calculation','Í stöðugu M/M/1-kerfi er komutaktur λ = 6 mál/klst. og þjónustutaktur μ = 10 mál/klst. Hver er meðalfjöldi mála í biðröð, Lq?',['0,9 mál.','1,5 mál.','0,6 mál.','2,5 mál.'],'ρ = λ/μ = 0,6. Lq = ρ²/(1−ρ) = 0,36/0,4 = 0,9 mál. Lq telur aðeins biðröðina, ekki málið í þjónustu.',queue,[]);
  add('F7','Biðraðir','calculation','Í stöðugu biðraðakerfi bíða að meðaltali 3 mál í röð og 12 mál koma á klukkustund. Hver er meðalbiðtími Wq?',['15 mínútur.','4 mínútur.','36 mínútur.','3 klukkustundir.'],'Wq = Lq/λ = 3/12 klst. = 0,25 klst. = 15 mínútur. Ekki rugla klukkustundum og mínútum saman.',queue,[]);
  add('F7','Biðraðir','calculation','Í stöðugu þjónustukerfi er meðalbið Wq = 12 mínútur. Hver þjónn afgreiðir að meðaltali 10 mál/klst. Hver er meðalheildartími máls í kerfinu?',['18 mínútur.','22 mínútur.','12 mínútur.','72 mínútur.'],'Meðalþjónustutíminn er 1/μ = 1/10 klst. = 6 mínútur. W = Wq + 1/μ = 12 + 6 = 18 mínútur.',queue,[]);
  add('F7','Biðraðir','application','Greinandi færir M/M/1-útreikning yfir í M/M/c-kerfi með fleiri þjónum. Hvaða varúð skiptir máli samkvæmt viðbótarefninu?',['Reikna þarf Lq með viðeigandi M/M/c-jöfnu; tengslin Wq = Lq/λ og W = Wq + 1/μ haldast.','Allar jöfnur M/M/1 haldast óbreyttar óháð fjölda þjóna.','Wq er alltaf núll þegar fleiri en einn þjónn vinnur.','Þjónustutíminn verður sá sami og biðtíminn þegar c er stærra en 1.'],'Myndin aðgreinir jöfnu Lq fyrir M/M/1 og M/M/c en sýnir að tengsl Wq, W og L gilda áfram. μ er þjónustutaktur eins þjóns.',queue,[]);
  const symbols=[
    ['timer-start','F4','Ferli á að hefjast klukkan 8 á hverjum mánudegi. Hvaða merkingu hefur táknið sem sést?',['Tímastýrður upphafsatburður.','Venjulegur endaatburður.','Samhliða hlið.','Skilaboðasending í miðju ferli.'],'Einfaldur þunnur hringur táknar upphaf. Klukkan merkir að tímasetning kveiki ferlið.',f4,[8],'Einfaldur þunnur hringur með klukku innan í.'],
    ['message-catch','F4','Hvað gerir táknið þegar tilvik kemur að því?',['Bíður eftir skilaboðum og heldur síðan áfram.','Sendir skilaboð og heldur áfram.','Lýkur öllum virkum leiðum ferlisins.','Klofnar í allar útleiðir samhliða.'],'Tvöfaldur hringur er milliatburður. Ófyllt umslag er catching message event: atburðurinn bíður eftir móttöku skilaboða.',f4,[12],'Tvöfaldur hringur með ófylltu umslagi.'],
    ['message-throw','F4','Hvaða túlkun á sýnda tákninu er rétt?',['Milliatburður sem sendir skilaboð.','Milliatburður sem bíður eftir skilaboðum.','Upphafsatburður sem bíður eftir dagsetningu.','Gagnahlutur sem geymir skrá.'],'Fyllt umslag merkir sendingu (throwing). Tvöfaldur þunnur hringur staðsetur atburðinn í miðju ferlis.',f4,[12,20],'Tvöfaldur hringur með dökku umslagi.'],
    ['boundary-timer','F4','Tímaatburðurinn er festur á jaðar verksins og hefur samfellda hringi. Hvað gerist ef hann virkjar á meðan verkið er enn í gangi?',['Verkið er rofið og farið eftir útleið tímaatburðarins.','Verkið heldur áfram og útleiðin er alltaf hunsuð.','Allt ferlið byrjar sjálfkrafa aftur frá upphafi.','Bið er sett á eftir verkinu, en verkið er aldrei rofið.'],'Samfelldur jaðaratburður er interrupting: hann stöðvar viðkomandi verk og virkjar undantekningarleið. Þetta er ekki einfaldlega bið eftir að verki lýkur.',f4,[20,28],'Verk með klukku á jaðrinum, samfelldum tvöföldum hring og útleið.'],
    ['noninterrupting-timer','F4','Hvað merkir slitna línan umhverfis sýndan tímaatburð á jaðri verksins?',['Við virkjun hefst viðbótarleið en verkið heldur áfram.','Verkið stöðvast strax þegar atburðurinn virkjar.','Atburðurinn getur aðeins verið upphaf ferlisins.','Táknið er skilaboðaflæði milli tveggja poola.'],'Slitnir hringir tákna non-interrupting boundary event. Tímaatburðurinn getur sett af stað t.d. áminningu án þess að stöðva aðalverkið.',f4,[20,29,30],'Verk með klukku á jaðrinum, slitnum tvöföldum hring og útleið.'],
    ['collapsed','F3','Hvað gefur plúsmerkið neðst í verkinu til kynna?',['Verkið er samanbrotinn undirferill með falin innri skref.','Allar útleiðir verksins verða alltaf keyrðar samtímis.','Verkið er skilyrt ákvörðun með nákvæmlega eina útleið.','Verkið er endaatburður með auka vinnslutíma.'],'Plúsmerki í litlum ferningi inni í aðgerð táknar collapsed sub-process. Plús inni í tígli væri AND-hlið, en hér er um undirferil að ræða.',f3,[33,34],'Rétthyrnd aðgerð með ávölum hornum og litlum ferningi með plús neðst.'],
    ['call','F3','Hvað gefur sérstaklega þykki ramminn á sýndu verki til kynna?',['Call activity sem kallar á endurnýtanlegan, sameiginlegan feril.','Verk sem tekur lengri tíma en öll önnur verk.','Verk sem á alltaf að keyra tvisvar.','Milliatburð sem er ekki hægt að stöðva.'],'Call activity hefur þykkan ramma og vísar á sameiginlega skilgreiningu sem má endurnýta. Ramminn segir ekki til um tíma eða fjölda endurtekninga.',f3,[7,36],'Aðgerð með þykkum ramma og litlu plúsmerki neðst.'],
    ['sequence','F3','Hvaða hlutverki gegnir sýnda línan í BPMN?',['Sýnir röð framkvæmdar innan ferlis.','Sýnir skilaboð milli tveggja sjálfstæðra poola.','Tengir eingöngu textaskýringu við verk.','Sýnir jákvætt orsakasamhengi í CLD.'],'Samfelld lína með fylltum örvaroddi er sequence flow og sýnir framvindu tilvika. Message flow hefur aðra framsetningu og tengir þátttakendur.',f3,[3],'Samfelld lína með fylltum örvaroddi.'],
    ['message-flow','F3','Í samstarfslíkani liggur sýnda línan milli tveggja poola. Hvað er hún?',['Skilaboðaflæði (message flow).','Raðflæði (sequence flow).','Samhliða sameining (AND-join).','Gögn sem eru geymd inni í einum verkþætti.'],'Slitin lína með opnum hring í upphafi og opnum örvaroddi táknar skilaboð milli þátttakenda. Hún flytur ekki sequence-flow token milli poola.',f3,[30,31,32],'Slitin lína frá litlum opnum hring að opnum örvaroddi.'],
    ['event-gateway','F4','Ferli bíður ýmist eftir svari frá birgi eða tímamörkum. Hvernig nýtist sýnda hliðið?',['Leið ræðst af því hvor atburðurinn verður fyrst.','Báðar leiðir eru alltaf virkjaðar þegar tilvik kemur.','Leið er valin eingöngu með útreikningi á þegar tiltækum gögnum.','Hliðið leggur saman kostnað úr öllum innleiðum.'],'Event-based gateway bíður eftir atburðum. Í þessu dæmi ræður fyrst komna svarið eða útrunninn tími því hvaða leið er farin.',f4,[10,22,26],'Tígull með tvöföldum hring og fimmhyrningi innan í.'],
    ['data','F3','Sýnda táknið er tengt aðgerð með gagnatengingu. Hvað táknar það?',['Gagnahlut sem aðgerð les eða býr til.','Sjálfstæðan þátttakanda með eigin ferli.','Endaatburð sem lokar tilviki.','Hlið sem velur eina af mörgum leiðum.'],'Data object sýnir upplýsingar eða skjal sem verk notar eða framleiðir. Það er ekki aðgerð og stýrir ekki sjálft flæði tilvika.',f3,[24,26],'Blaðlaga tákn með brotnu efra hægra horni.']
  ];
  for(const [symbol,lecture,stem,options,explanation,file,pages,alt]of symbols)add(lecture,'BPMN-tákn','diagram',stem,options,explanation,file,pages,{type:'symbol',symbol,alt});
  add('F3','Val á hliði','diagram','Eftir A á að framkvæma bæði B og C óháð hvort öðru. D má hefjast þegar bæði eru búin. Hvaða tákn á að koma í stað spurningarmerkisins?',['Plúsmerki: AND-klofnun.','X: XOR-klofnun.','Umslag: skilaboðaatburður.','Tómur hringur: upphafsatburður.'],'Báðar greinar eiga alltaf að vera virkjaðar og AND-sameining bíður eftir þeim báðum. Því passar AND-klofnun við lýsinguna.',f3,[16],{type:'branch',split:'?',join:'+',before:'A',top:'B',bottom:'C',after:'D'});
  add('F3','Val á hliði','diagram','Eftir A er nákvæmlega önnur greinin, B eða C, farin. D á að hefjast um leið og sú grein lýkur. Hvaða hlið vantar við sameininguna?',['XOR-sameining.','AND-sameining.','Tímastýrt upphafshlið.','Hlið sem virkjar báðar greinar aftur.'],'XOR-sameining tekur við því tilviki sem kemur af valinni leið og bíður ekki eftir óvirkri grein. AND-sameining myndi bíða eftir báðum innleiðum.',f3,[15],{type:'branch',split:'X',join:'?',before:'A',top:'B',bottom:'C',after:'D'});
  const f1='F1 - Kynning á námskeiði (1).pdf';
  add('F1','Lean','application','Viðskiptavinir bíða lengi meðan starfsfólk leitar að gögnum og skráir sömu upplýsingar tvisvar. Hvaða áhersla lýsir best Lean-nálgun á vandann?',['Greina og draga úr sóun til að bæta flæði og virði fyrir viðskiptavin.','Byrja á vottun skjala án þess að skoða flæðið.','Hámarka nýtingu hverrar deildar óháð bið viðskiptavina.','Sjálfvirknivæða öll núverandi skref áður en þörf þeirra er metin.'],'Lean leggur áherslu á að draga úr sóun og auka virði út frá viðskiptavininum. Bið og tvíverknaður gefa tilefni til að skoða flæði og nauðsyn skrefa.',f1,[14]);
  add('F1','Six Sigma','application','Gæði framleiðslu sveiflast mikið milli daga. Teymi notar mæligögn og tölfræðiaðferðir í DMAIC-verkefni til að draga úr frávikum. Hvaða nálgun er skýrast lýst?',['Six Sigma.','SIPOC sem fullbúin lausn án frekari greiningar.','RACI sem aðferð til að reikna dreifingu gæða.','CJM sem mæling á breytileika framleiðslu.'],'Six Sigma leggur áherslu á minni breytileika og færri mistök með sannreynanlegum gögnum og tölfræðiaðferðum. DMAIC er verkefnaröðin sem glærurnar nefna.',f1,[15]);
  add('F1','Gæðastjórnun','application','Fyrirtæki hefur fengið gæðavottun en viðskiptavinir kvarta enn um tvíverknað og hæga afgreiðslu. Hver er best studda ályktunin?',['Vottun kemur ekki í stað þess að greina og bæta raunverulega ferla.','Vottun sannar að kvartanir geti ekki stafað af ferlum.','Fyrirtækið þarf eingöngu að fjölga skjölum til að leysa vandann.','BPM á aðeins við áður en fyrirtæki fær vottun.'],'F1 bendir á að áhugi á vottun geti orðið meiri en áhugi á gæðum og að ISO eitt og sér gangi ekki nógu langt í ferlaumbótum. Raunveruleg frammistaða þarf áfram athygli.',f1,[13]);
  add('F1','Nýtni og markvirkni','application','Úrvinnsla máls styttist úr 20 í 12 mínútur án breytinga á gæðum eða nákvæmni. Hvaða árangur er beinast sýndur?',['Aukin nýtni (efficiency).','Aukin markvirkni eingöngu vegna meiri nákvæmni.','Aukinn biðtími í ferlinu.','Aukin formleg ábyrgð samkvæmt RACI.'],'Nýtni eykst þegar sama gæðastigi er náð með minni tíma eða fyrirhöfn. Dæmið segir ekki að nákvæmni hafi aukist.',f1,[19]);
  add('F1','Nýtni og markvirkni','application','Tími og fyrirhöfn við afgreiðslu haldast óbreytt en hlutfall rangra niðurstaðna lækkar úr 8% í 2%. Hvaða árangur er beinast sýndur?',['Aukin markvirkni (effectiveness).','Aukin nýtni eingöngu vegna styttri vinnslutíma.','Styttri heildarhringrásartími samkvæmt gefnum upplýsingum.','Aukin framleiðslugeta samkvæmt gefnum upplýsingum.'],'Glæran tengir markvirkni við færri mistök eða meiri gæði og nákvæmni við sömu fyrirhöfn. Tíminn styttist ekki samkvæmt dæminu.',f1,[19]);
  return questions;
})();
